args.content:
/*
** klua - a from-scratch Lua 5.5-compatible interpreter (clean-room reimplementation)
** core.h - shared internal API between the interpreter core and library modules.
**
** Library module authors: everything you need is declared here. You write
** C functions of type ls_CFunc and register them with ls_reglib(). See
** src/base.c for a complete working example.
*/
#ifndef KLUA_CORE_H
#define KLUA_CORE_H

#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include <setjmp.h>

typedef int64_t  ls_Int;
typedef uint64_t ls_Uint;
typedef double   ls_Flt;

typedef struct ls_State ls_State;
typedef struct ls_Value ls_Value;
typedef int (*ls_CFunc)(ls_State *S);

/* ------------------------------------------------------------------ */
/* Value model                                                        */
/* ------------------------------------------------------------------ */

typedef enum {
  LS_TNIL = 0, LS_TFALSE, LS_TTRUE, LS_TINT, LS_TFLT,
  LS_TSTR, LS_TTABLE, LS_TFUNC, LS_TCFUNC, LS_TTHREAD, LS_TUDATA
} ls_Type;

typedef struct ls_Str {
  uint32_t hash;
  uint32_t len;
  struct ls_Str *next;   /* intern table chain */
  char data[1];
} ls_Str;

struct ls_Value {
  int tag;
  union {
    ls_Int i;
    ls_Flt f;
    ls_Str *s;
    struct ls_Table *t;
    struct ls_Closure *cl;
    ls_CFunc cf;
    ls_State *th;        /* coroutine */
    struct ls_UData *ud;
  } u;
};

typedef struct ls_TNode {
  ls_Value k, v;
  int next;              /* index+1 of next node in chain, 0 = none */
} ls_TNode;

typedef struct ls_Table {
  ls_Value *arr;         /* array part: indices 1..asize */
  unsigned asize;
  ls_TNode *node;        /* hash part */
  unsigned nsize;        /* power of 2; 0 = no hash */
  unsigned nused;        /* live entries in hash */
  struct ls_Table *meta;
} ls_Table;

typedef struct ls_Upval {
  ls_Value *ptr;         /* points to frame slot while open, to &v when closed */
  ls_Value v;
  struct ls_Upval *next; /* open-upvalue list of frame (only while open) */
} ls_Upval;

struct ls_Node;          /* AST node (parse.c) */

typedef struct ls_Proto {
  struct ls_Node *body;
  int nparams;
  int isvararg;
  int nslots;            /* frame size (locals) */
  int nups;              /* number of upvalues */
  int *upinslot;         /* per upvalue: parent frame slot, or -1 */
  int *upupidx;          /* per upvalue: parent upvalue index when upinslot<0 */
  char **upnames;
  char *chunk;           /* chunk name, e.g. "@file.lua" or source string */
  int line, lastline;
  char **locnames;       /* slot -> local name (for error messages), size nslots */
  int *locline;
} ls_Proto;

typedef struct ls_Closure {
  ls_Proto *p;
  ls_Upval **ups;
} ls_Closure;

typedef struct ls_UData {
  void *ptr;             /* payload (size given at creation) */
  ls_Table *meta;
} ls_UData;

/* ------------------------------------------------------------------ */
/* Call info (call stack, for tracebacks and error positions)         */
/* ------------------------------------------------------------------ */

typedef struct ls_CallInfo {
  int line;              /* current line (Lua frames) */
  ls_Proto *p;           /* Lua function (NULL for C) */
  ls_CFunc cf;           /* C function (NULL for Lua) */
  const char *name;      /* static string describing callee name, may be NULL */
  const char *namewhat;  /* "global","local","field","method","upvalue","for iterator","metamethod", or "" */
  int istail;
  int nresults;          /* expected results (for C call protocol) */
} ls_CallInfo;

/* ------------------------------------------------------------------ */
/* State (one per coroutine)                                          */
/* ------------------------------------------------------------------ */

typedef struct ls_ErrJmp {
  jmp_buf b;
  struct ls_ErrJmp *prev;
  int status;            /* set by longjmp side */
} ls_ErrJmp;

struct ls_State {
  struct ls_Global *g;
  /* value stack: used for C call protocol and multi-value plumbing */
  ls_Value *st;
  int top, cap;
  /* call stack */
  ls_CallInfo *cis;
  int nci, capci;
  /* error handling */
  ls_ErrJmp *errjmp;
  ls_Value errobj;
  int errinhandle;
  /* coroutine machinery */
  int status;            /* LS_COSUSP, LS_CORUN, LS_CONORMAL, LS_CODEAD */
  int ismain;
  int started;
  ls_State *resumer;
  ls_Value body;         /* function to run (before start) */
  void *ctx[2];          /* opaque: ucontext pointers */
  char *cstack;
  int closeerr;          /* pending error from closing */
};

#define LS_COSUSP   0
#define LS_CORUN    1
#define LS_CONORMAL 2
#define LS_CODEAD   3

typedef struct ls_Global {
  ls_Table *strt;        /* string intern table (as raw buckets) */
  ls_Str **strhash; unsigned strhsize; unsigned strcount;
  ls_Table *globals;     /* _G */
  ls_Table *registry;
  ls_Table *loaded;      /* package.loaded */
  ls_Table *preload;     /* package.preload */
  ls_Table *mt_string;   /* metatable for strings */
  ls_State *mainco;
  ls_State *cur;         /* current running coroutine */
  ls_Table *mt[LS_TUDATA+1]; /* per-type metatables (for debug.setmetatable) */
  int warnings;
  /* GC accounting: we never collect; keep a plausible counter */
  size_t gcdebt;
  uint64_t randstate[4]; /* xoshiro state, seeded at startup */
  /* pending finalizers */
  ls_Value *finlist; int nfin, capfin;
} ls_Global;

/* ------------------------------------------------------------------ */
/* Value constructors / predicates                                    */
/* ------------------------------------------------------------------ */

ls_Value ls_nil(void);
ls_Value ls_bool(int b);
ls_Value ls_int(ls_Int i);
ls_Value ls_flt(ls_Flt f);
ls_Value ls_str(ls_State *S, const char *s);
ls_Value ls_strn(ls_State *S, const char *s, size_t n);
ls_Value ls_strf(ls_State *S, const char *fmt, ...);
ls_Value ls_table(ls_State *S);
ls_Value ls_cfunc(ls_State *S, ls_CFunc f);
ls_Value ls_udata(ls_State *S, size_t sz, ls_Table *meta); /* payload zeroed */
int      ls_type(ls_Value v);            /* LS_T* */
const char *ls_typename(ls_Value v);     /* "nil","boolean","number","string",... */
int      ls_truthy(ls_Value v);          /* not nil and not false */
int      ls_isfalse(ls_Value v);

#define ls_vstr(v)   ((v).u.s->data)
#define ls_vstrlen(v) ((v).u.s->len)

/* number conversions */
int ls_toint(ls_Value v, ls_Int *out);   /* strict: numeric, integral, fits */
int ls_toflt(ls_Value v, ls_Flt *out);   /* numeric (int or float) */
int ls_str2num(const char *s, size_t n, ls_Value *out); /* full lua string->number */

/* ------------------------------------------------------------------ */
/* Value stack (call protocol)                                        */
/* ------------------------------------------------------------------ */

void ls_push(ls_State *S, ls_Value v);
ls_Value ls_pop(ls_State *S);
ls_Value ls_topv(ls_State *S);
int  ls_narg(ls_State *S);               /* args of current C function */
ls_Value ls_arg(ls_State *S, int i);     /* 1-based; nil if absent */
void ls_pushnil(ls_State *S);
void ls_pushint(ls_State *S, ls_Int i);
void ls_pushflt(ls_State *S, ls_Flt f);
void ls_pushstr(ls_State *S, const char *s);
void ls_pushbool(ls_State *S, int b);

/* call the value at (top-nargs-1): pops func+args, pushes nret results */
void ls_call(ls_State *S, int nargs, int nret);
/* protected: returns 0 on success (nret results pushed), nonzero on error
   (single error value pushed). */
int  ls_pcall(ls_State *S, int nargs, int nret);

/* call a plain value (not via stack) */
void ls_callv(ls_State *S, ls_Value f, ls_Value *args, int nargs,
              ls_Value *rets, int *nret); /* rets must hold *nret slots */

/* ------------------------------------------------------------------ */
/* Tables (respect metamethods unless raw)                            */
/* ------------------------------------------------------------------ */

ls_Value ls_get(ls_State *S, ls_Value t, ls_Value k);        /* t[k] w/ mm */
ls_Value ls_rawget(ls_State *S, ls_Value t, ls_Value k);     /* no mm; nil if absent */
void     ls_set(ls_State *S, ls_Value t, ls_Value k, ls_Value v);   /* t[k]=v w/ mm */
void     ls_rawset(ls_State *S, ls_Value t, ls_Value k, ls_Value v);
ls_Value ls_geti(ls_State *S, ls_Value t, ls_Int i);
void     ls_seti(ls_State *S, ls_Value t, ls_Int i, ls_Value v);
ls_Value ls_rawgeti(ls_State *S, ls_Value t, ls_Int i);
void     ls_rawseti(ls_State *S, ls_Value t, ls_Int i, ls_Value v);
ls_Value ls_getfield(ls_State *S, ls_Value t, const char *k);
void     ls_setfield(ls_State *S, ls_Value t, const char *k, ls_Value v);
ls_Int   ls_len(ls_State *S, ls_Value v);                    /* #v w/ mm */
ls_Int   ls_rawlen(ls_State *S, ls_Value v);                 /* tables/strings only */
int      ls_next(ls_State *S, ls_Value t, ls_Value *k, ls_Value *v); /* 0 at end */
ls_Table *ls_meta(ls_State *S, ls_Value v);                  /* metatable or NULL */
void     ls_setmeta(ls_State *S, ls_Value v, ls_Table *mt);
ls_Value ls_getmeta_field(ls_State *S, ls_Value v, const char *fld); /* raw from meta */

/* globals */
ls_Value ls_getglobal(ls_State *S, const char *name);
void     ls_setglobal(ls_State *S, const char *name, ls_Value v);

/* ------------------------------------------------------------------ */
/* Errors                                                             */
/* ------------------------------------------------------------------ */

/* Throw a Lua error with a string value; position of the nearest running
   Lua frame (level 1 style, like luaL_error) is prepended. Never returns. */
void ls_error(ls_State *S, const char *fmt, ...);
/* Throw without position prefix. Never returns. */
void ls_errorraw(ls_State *S, ls_Value v);
/* bad argument #i to 'fn' (msg), with position. Never returns. */
void ls_argerror(ls_State *S, int i, const char *fn, const char *msg);
/* "(type expected, got type)" style arg error. Never returns. */
void ls_typeerror(ls_State *S, int i, const char *fn, const char *tname);

/* argument checking helpers (use current function's registered name) */
void      ls_checkany(ls_State *S, int i);
ls_Int    ls_checkint(ls_State *S, int i);
ls_Int    ls_optint(ls_State *S, int i, ls_Int def);
ls_Flt    ls_checknum(ls_State *S, int i);
ls_Flt    ls_optnum(ls_State *S, int i, ls_Flt def);
const char *ls_checkstr(ls_State *S, int i, size_t *len);
