/* ---------------- basic values ---------------- */

ls_Value ls_nil(void) { ls_Value v; v.tag = LS_TNIL; v.u.i = 0; return v; }
ls_Value ls_bool(int b) { ls_Value v; v.tag = b ? LS_TTRUE : LS_TFALSE; v.u.i = 0; return v; }
ls_Value ls_int(ls_Int i) { ls_Value v; v.tag = LS_TINT; v.u.i = i; return v; }
ls_Value ls_flt(ls_Flt f) { ls_Value v; v.tag = LS_TFLT; v.u.f = f; return v; }

int ls_type(ls_Value v) { return v.tag; }

const char *ls_typename(ls_Value v) {
  switch (v.tag) {
    case LS_TNIL: return "nil";
    case LS_TFALSE: case LS_TTRUE: return "boolean";
    case LS_TINT: case LS_TFLT: return "number";
    case LS_TSTR: return "string";
    case LS_TTABLE: return "table";
    case LS_TFUNC: case LS_TCFUNC: return "function";
    case LS_TTHREAD: return "thread";
    case LS_TUDATA: return "userdata";
  }
  return "?";
}

int ls_truthy(ls_Value v) { return v.tag != LS_TNIL && v.tag != LS_TFALSE; }
int ls_isfalse(ls_Value v) { return v.tag == LS_TNIL || v.tag == LS_TFALSE; }

int ls_rawequal(ls_Value a, ls_Value b) {
  if (a.tag != b.tag) {
    /* int/float mixing is never rawequal (tags differ) */
    if ((a.tag == LS_TINT && b.tag == LS_TFLT) || (a.tag == LS_TFLT && b.tag == LS_TINT))
      return 0;
    return 0;
  }
  switch (a.tag) {
    case LS_TNIL: return 1;
    case LS_TFALSE: case LS_TTRUE: return 1;
    case LS_TINT: return a.u.i == b.u.i;
    case LS_TFLT: return a.u.f == b.u.f;
    case LS_TSTR: return a.u.s == b.u.s;
    case LS_TTABLE: return a.u.t == b.u.t;
    case LS_TFUNC: case LS_TCFUNC:
      if (a.tag == LS_TCFUNC) return a.u.cf == b.u.cf;
      return a.u.cl == b.u.cl;
    case LS_TTHREAD: return a.u.th == b.u.th;
    case LS_TUDATA: return a.u.ud == b.u.ud;
  }
  return 0;
}

/* ---------------- string interning ---------------- */

static uint32_t str_hash(const char *s, size_t n) {
  uint32_t h = (uint32_t)n;
  size_t step = (n >> 5) + 1;
  for (size_t i = n; i >= step; i -= step)
    h = h * 33 + (unsigned char)s[i-1];
  return h;
}

ls_Value ls_strn(ls_State *S, const char *s, size_t n) {
  ls_Global *g = S->g;
  if (g->strhsize == 0) {
    g->strhsize = 128;
    g->strhash = calloc(g->strhsize, sizeof(ls_Str*));
  }
  uint32_t h = str_hash(s, n);
  unsigned idx = h & (g->strhsize - 1);
  for (ls_Str *p = g->strhash[idx]; p; p = p->next)
    if (p->len == n && p->hash == h && memcmp(p->data, s, n) == 0) {
      ls_Value v; v.tag = LS_TSTR; v.u.s = p; return v;
    }
  /* grow if needed */
  if (g->strcount >= g->strhsize) {
    unsigned ns = g->strhsize * 2;
    ls_Str **nh = calloc(ns, sizeof(ls_Str*));
    for (unsigned i = 0; i < g->strhsize; i++) {
      ls_Str *p = g->strhash[i];
      while (p) {
        ls_Str *nx = p->next;
        unsigned ni = p->hash & (ns - 1);
        p->next = nh[ni]; nh[ni] = p;
        p = nx;
      }
    }
    free(g->strhash);
    g->strhash = nh; g->strhsize = ns;
    idx = h & (ns - 1);
  }
  ls_Str *p = malloc(sizeof(ls_Str) + n);
  p->hash = h; p->len = (uint32_t)n;
  memcpy(p->data, s, n);
  p->data[n] = '\0';
  p->next = g->strhash[idx];
  g->strhash[idx] = p;
  g->strcount++;
  g->gcdebt += n + sizeof(ls_Str);
  ls_Value v; v.tag = LS_TSTR; v.u.s = p; return v;
}

ls_Value ls_str(ls_State *S, const char *s) { return ls_strn(S, s, strlen(s)); }

ls_Value ls_strf(ls_State *S, const char *fmt, ...) {
  char buf[512];
  va_list ap;
  va_start(ap, fmt);
  vsnprintf(buf, sizeof(buf), fmt, ap);
  va_end(ap);
  return ls_str(S, buf);
}

