/* ---------------- number formatting ---------------- */

void ls_fmtint(char *buf, ls_Int i) { sprintf(buf, "%" PRId64, i); }

void ls_fmtflt(char *buf, ls_Flt f) {
  sprintf(buf, "%.14g", f);
  /* make integral floats look like floats: append ".0" */
  if (isfinite(f)) {
    if (!strpbrk(buf, ".nN") && !strchr(buf, 'e') && !strchr(buf, 'E') &&
        !strchr(buf, 'i') && !strchr(buf, 'I'))
      strcat(buf, ".0");
  }
}

/* convert a string (fully) to number per lua rules; accepts surrounding
   spaces, hex, hex floats, exponents. Returns 1 on success. */
int ls_str2num(const char *s, size_t n, ls_Value *out) {
  char buf[128];
  while (n > 0 && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r' || *s == '\v' || *s == '\f')) { s++; n--; }
  while (n > 0 && (s[n-1] == ' ' || s[n-1] == '\t' || s[n-1] == '\n' || s[n-1] == '\r' || s[n-1] == '\v' || s[n-1] == '\f')) n--;
  if (n == 0 || n >= sizeof(buf)) return 0;
  memcpy(buf, s, n); buf[n] = '\0';
  /* reject inf/nan spellings? C strtod accepts them; lua's lexer does not.
     Lua's tonumber via l_strton uses strtod/strtoull-like parsing but
     rejects trailing chars. It does accept "inf"? No: lua number parsing
     only accepts decimal/hex numerals. Reject non-numeric lead chars. */
  const char *p = buf;
  if (*p == '+' || *p == '-') p++;
  int ishex = (p[0] == '0' && (p[1] == 'x' || p[1] == 'X'));
  if (!ishex && !isdigit((unsigned char)*p) && *p != '.') return 0;
  if (*p == '.' && !isdigit((unsigned char)p[1])) return 0;
  char *end;
  if (ishex) {
    /* hex: integer if no '.', 'p', 'P' */
    int isfloat = 0;
    for (const char *q = p + 2; *q; q++)
      if (*q == '.' || *q == 'p' || *q == 'P') { isfloat = 1; break; }
    if (!isfloat) {
      errno = 0;
      unsigned long long u = strtoull(buf, &end, 16);
      if (end != buf + n) return 0;
      if (errno == ERANGE) return 0; /* too many digits: lua wraps for hex? it wraps via strtoull saturation... treat as fail */
      out->tag = LS_TINT; out->u.i = (ls_Int)u;
      return 1;
    }
    double d = strtod(buf, &end);
    if (end != buf + n) return 0;
    out->tag = LS_TFLT; out->u.f = d;
    return 1;
  }
  /* decimal: integer if pure digits (with sign) */
  int pure = 1;
  for (const char *q = p; *q; q++)
    if (!isdigit((unsigned char)*q)) { pure = 0; break; }
  if (pure) {
    errno = 0;
    long long v = strtoll(buf, &end, 10);
    if (end == buf + n && errno != ERANGE) {
      out->tag = LS_TINT; out->u.i = v;
      return 1;
    }
    if (end != buf + n) return 0;
    /* overflow: falls to float */
  }
  errno = 0;
  double d = strtod(buf, &end);
  if (end != buf + n) return 0;
  /* validate it's a proper lua numeral (strtod also accepts "infinity" etc.
     but we filtered lead chars; also filter hex handled above) */
  out->tag = LS_TFLT; out->u.f = d;
  return 1;
}

int ls_toint(ls_Value v, ls_Int *out) {
  if (v.tag == LS_TINT) { *out = v.u.i; return 1; }
  if (v.tag == LS_TFLT) {
    ls_Flt f = v.u.f;
    if (f >= (ls_Flt)INT64_MIN && f < 9223372036854775808.0 && floor(f) == f) {
      *out = (ls_Int)f; return 1;
    }
    /* INT64_MIN edge */
    if (f == (ls_Flt)INT64_MIN) { *out = INT64_MIN; return 1; }
    return 0;
  }
  return 0;
}

int ls_toflt(ls_Value v, ls_Flt *out) {
  if (v.tag == LS_TINT) { *out = (ls_Flt)v.u.i; return 1; }
  if (v.tag == LS_TFLT) { *out = v.u.f; return 1; }
  return 0;
}

/* ---------------- tables ---------------- */

ls_Value ls_table(ls_State *S) {
  ls_Table *t = calloc(1, sizeof(ls_Table));
  S->g->gcdebt += sizeof(ls_Table);
  ls_Value v; v.tag = LS_TTABLE; v.u.t = t; return v;
}

static unsigned hash_int(ls_Uint k) {
  k ^= k >> 33; k *= 0xff51afd7ed558ccdULL;
  k ^= k >> 33;
  return (unsigned)k;
}

static unsigned key_hash(ls_Value k) {
  switch (k.tag) {
    case LS_TINT: return hash_int((ls_Uint)k.u.i);
    case LS_TFLT: { double d = k.u.f; uint64_t b; memcpy(&b, &d, 8); return hash_int(b); }
    case LS_TSTR: return k.u.s->hash;
    case LS_TTRUE: return 0x1234;
    default: return hash_int((ls_Uint)(uintptr_t)k.u.t);
  }
}

static int key_eq(ls_Value a, ls_Value b) {
  if (a.tag == LS_TNIL) return 0;
  if (a.tag == LS_TINT && b.tag == LS_TFLT) {
    ls_Int i; if (!ls_toint(b, &i)) return 0; return a.u.i == i;
  }
  if (a.tag == LS_TFLT && b.tag == LS_TINT) {
    ls_Int i; if (!ls_toint(a, &i)) return 0; return i == b.u.i;
  }
  return ls_rawequal(a, b);
}

static ls_Value *hash_find(ls_Table *t, ls_Value k) {
  if (t->nsize == 0) return NULL;
  unsigned m = t->nsize - 1;
  unsigned i = key_hash(k) & m;
  int idx = (int)i;
  while (1) {
    ls_TNode *nd = &t->node[idx];
    if (nd->v.tag == LS_TNIL && nd->k.tag == LS_TNIL) return NULL; /* empty */
    if (key_eq(nd->k, k)) return &nd->v;
    if (nd->next == 0) return NULL;
    idx = nd->next - 1;
  }
}

static void tbl_grow_hash(ls_State *S, ls_Table *t, unsigned nsize);

ls_Value ls_rawget(ls_State *S, ls_Value t, ls_Value k) {
  (void)S;
  if (t.tag != LS_TTABLE) return ls_nil();
  ls_Table *tb = t.u.t;
  if (k.tag == LS_TINT && k.u.i >= 1 && (ls_Uint)k.u.i <= tb->asize)
    return tb->arr[k.u.i - 1];
  if (k.tag == LS_TFLT) { ls_Int i; if (ls_toint(k, &i)) k = ls_int(i); }
  ls_Value *r = hash_find(tb, k);
  return r ? *r : ls_nil();
}

ls_Value ls_rawgeti(ls_State *S, ls_Value t, ls_Int i) {
  return ls_rawget(S, t, ls_int(i));
}

/* insert into hash; assumes key not present */
static void hash_insert(ls_State *S, ls_Table *t, ls_Value k, ls_Value v) {
  if (t->nsize == 0 || (t->nused + 1) * 2 > t->nsize)
    tbl_grow_hash(S, t, t->nsize ? t->nsize * 2 : 8);
  unsigned m = t->nsize - 1;
  unsigned mi = key_hash(k) & m;
  ls_TNode *main_nd = &t->node[mi];
  if (main_nd->k.tag != LS_TNIL || main_nd->v.tag != LS_TNIL) {
    /* occupied: find free slot from end */
    int free_i = -1;
    for (int i = (int)t->nsize - 1; i >= 0; i--)
      if (t->node[i].k.tag == LS_TNIL && t->node[i].v.tag == LS_TNIL) { free_i = i; break; }
    if (free_i < 0) { tbl_grow_hash(S, t, t->nsize * 2); hash_insert(S, t, k, v); return; }
    /* is the occupant in its main position? */
    unsigned occ_main = key_hash(main_nd->k) & m;
    ls_TNode *freen = &t->node[free_i];
    if (occ_main == mi) {
      /* chain it */
      freen->k = k; freen->v = v;
      freen->next = main_nd->next;
      main_nd->next = free_i + 1;
    } else {
      /* move occupant out */
      int prev = (int)occ_main;
      while (t->node[prev].next != mi + 1) prev = t->node[prev].next - 1;
      t->node[prev].next = free_i + 1;
      *freen = *main_nd;
      main_nd->k = k; main_nd->v = v; main_nd->next = 0;
    }
  } else {
    main_nd->k = k; main_nd->v = v; main_nd->next = 0;
  }
  t->nused++;
}

/* count integer keys in [1..n] (array+hash) */
static unsigned count_ints(ls_Table *t, unsigned n) {
  unsigned c = 0;
  for (unsigned i = 1; i <= t->asize && i <= n; i++)
    if (t->arr[i-1].tag != LS_TNIL) c++;
  if (t->nsize) {
    for (unsigned i = 0; i < t->nsize; i++) {
      ls_TNode *nd = &t->node[i];
      if (nd->v.tag != LS_TNIL && nd->k.tag == LS_TINT &&
          nd->k.u.i >= 1 && (ls_Uint)nd->k.u.i <= n) c++;
    }
  }
  return c;
}

static void tbl_rehash(ls_State *S, ls_Table *t) {
  /* compute best new array size */
  unsigned best = 0;
  unsigned c = 0;
  /* check sizes 1,2,4,... */
  for (unsigned n = 1; ; n *= 2) {
    c = count_ints(t, n);
    if (c > n / 2) best = n;
    if (n >= 4096 || (n > 16 && c <= n / 2 && best == 0)) {
      /* heuristic stop */
    }
    if (n >= (1u<<20)) break;
    if (c < n / 2 && n >= 16) {
      /* continue a bit more */
    }
    if (n >= 1u << 20) break;
    if (n > 4096 && c <= n/2) break;
  }
  /* simpler lua-like: only grow when half full; but keep best */
  unsigned newsize = best;
  /* collect all hash entries */
  unsigned cnt = 0;
  for (unsigned i = 0; i < t->nsize; i++)
    if (t->node[i].v.tag != LS_TNIL && t->node[i].k.tag != LS_TNIL) cnt++;
  /* old array values beyond newsize move to hash */
  ls_Value *oldarr = t->arr;
  unsigned oldasize = t->asize;
  t->arr = newsize ? malloc(newsize * sizeof(ls_Value)) : NULL;
  for (unsigned i = 0; i < newsize; i++) t->arr[i] = ls_nil();
  for (unsigned i = 0; i < oldasize && i < newsize; i++) t->arr[i] = oldarr[i];
  /* snapshot hash entries that stay in hash */
  ls_Value *ks = malloc(sizeof(ls_Value) * (cnt + oldasize + 1));
  ls_Value *vs = malloc(sizeof(ls_Value) * (cnt + oldasize + 1));
  unsigned nk = 0;
  for (unsigned i = 0; i < t->nsize; i++) {
    ls_TNode *nd = &t->node[i];
    if (nd->v.tag != LS_TNIL && nd->k.tag != LS_TNIL) {
      if (nd->k.tag == LS_TINT && nd->k.u.i >= 1 && (ls_Uint)nd->k.u.i <= newsize)
        t->arr[nd->k.u.i - 1] = nd->v;
      else { ks[nk] = nd->k; vs[nk] = nd->v; nk++; }
    }
  }
  for (unsigned i = newsize; i < oldasize; i++)
    if (oldarr[i].tag != LS_TNIL) { ks[nk] = ls_int(i + 1); vs[nk] = oldarr[i]; nk++; }
  t->asize = newsize;
  t->nsize = 0; t->nused = 0;
  free(t->node); t->node = NULL;
  for (unsigned i = 0; i < nk; i++) hash_insert(S, t, ks[i], vs[i]);
  free(ks); free(vs); free(oldarr);
  S->g->gcdebt += 64;
}

static void tbl_grow_hash(ls_State *S, ls_Table *t, unsigned nsize) {
  (void)S;
  ls_TNode *old = t->node;
  unsigned oldn = t->nsize;
  t->node = calloc(nsize, sizeof(ls_TNode));
  unsigned oldsize_flag = t->nsize;
  t->nsize = nsize; t->nused = 0;
  (void)oldsize_flag;
  for (unsigned i = 0; i < oldn; i++)
    if (old[i].v.tag != LS_TNIL && old[i].k.tag != LS_TNIL) {
      /* reinsert preserving semantics */
      unsigned m = nsize - 1;
      unsigned mi = key_hash(old[i].k) & m;
      /* simple insert: find free slot chain style */
      if (t->node[mi].k.tag == LS_TNIL && t->node[mi].v.tag == LS_TNIL) {
        t->node[mi].k = old[i].k; t->node[mi].v = old[i].v; t->node[mi].next = 0;
      } else {
        int free_i = -1;
        for (int j = (int)nsize - 1; j >= 0; j--)
          if (t->node[j].k.tag == LS_TNIL && t->node[j].v.tag == LS_TNIL) { free_i = j; break; }
        unsigned occ_main = key_hash(t->node[mi].k) & m;
        ls_TNode *freen = &t->node[free_i];
        if (occ_main == mi) {
          freen->k = old[i].k; freen->v = old[i].v;
          freen->next = t->node[mi].next;
          t->node[mi].next = free_i + 1;
        } else {
          int prev = (int)occ_main;
          while (t->node[prev].next != mi + 1) prev = t->node[prev].next - 1;
          t->node[prev].next = free_i + 1;
          *freen = t->node[mi];
          t->node[mi].k = old[i].k; t->node[mi].v = old[i].v; t->node[mi].next = 0;
        }
      }
      t->nused++;
    }
  free(old);
}

void ls_rawset(ls_State *S, ls_Value t, ls_Value k, ls_Value v) {
  ls_Table *tb = t.u.t;
  if (k.tag == LS_TFLT) { ls_Int i; if (ls_toint(k, &i)) k = ls_int(i); }
  if (k.tag == LS_TNIL)
    ls_errorraw(S, ls_str(S, "table index is nil"));
  if (k.tag == LS_TFLT && isnan(k.u.f))
    ls_errorraw(S, ls_str(S, "table index is NaN"));
  if (k.tag == LS_TINT && k.u.i >= 1) {
    if ((ls_Uint)k.u.i <= tb->asize) {
      tb->arr[k.u.i - 1] = v;
      return;
    }
    /* maybe extend array part */
    if (tb->asize < 64 && (ls_Uint)k.u.i == tb->asize + 1 && v.tag != LS_TNIL) {
      tb->arr = realloc(tb->arr, (tb->asize + 1) * sizeof(ls_Value));
      tb->arr[tb->asize] = v;
      tb->asize++;
      return;
    }
  }
  ls_Value *old = hash_find(tb, k);
  if (old) { *old = v; return; }
  if (v.tag == LS_TNIL) return;
  hash_insert(S, tb, k, v);
}

void ls_rawseti(ls_State *S, ls_Value t, ls_Int i, ls_Value v) {
  ls_rawset(S, t, ls_int(i), v);
}

ls_Int ls_rawlen(ls_State *S, ls_Value v) {
  (void)S;
  if (v.tag == LS_TSTR) return (ls_Int)v.u.s->len;
  if (v.tag != LS_TTABLE) return 0;
  ls_Table *t = v.u.t;
  /* border: binary search in array part */
  unsigned lo = 0, hi = t->asize;
  /* arr[0..asize-1]; find first nil */
  while (lo < hi) {
    unsigned mid = (lo + hi) / 2;
    if (t->arr[mid].tag == LS_TNIL) hi = mid; else lo = mid + 1;
  }
  unsigned border = lo; /* arr[border] is nil or border==asize */
  if (border == t->asize) {
    /* array full; extend into hash */
    while (1) {
      ls_Value nx = ls_rawget(S, v, ls_int((ls_Int)border + 1));
      if (nx.tag == LS_TNIL) break;
      border++;
    }
  }
  return (ls_Int)border;
}

int ls_next(ls_State *S, ls_Value t, ls_Value *k, ls_Value *v) {
  (void)S;
  ls_Table *tb = t.u.t;
  if (k->tag == LS_TNIL) {
    /* start: first array element */
    for (unsigned i = 0; i < tb->asize; i++)
      if (tb->arr[i].tag != LS_TNIL) { *k = ls_int(i + 1); *v = tb->arr[i]; return 1; }
    /* then first hash node */
    for (unsigned i = 0; i < tb->nsize; i++)
      if (tb->node[i].v.tag != LS_TNIL && tb->node[i].k.tag != LS_TNIL) {
        *k = tb->node[i].k; *v = tb->node[i].v; return 1;
      }
    return 0;
  }
  /* find position after k */
  if (k->tag == LS_TINT && k->u.i >= 1 && (ls_Uint)k->u.i <= tb->asize) {
    for (unsigned i = (unsigned)k->u.i; i < tb->asize; i++)
      if (tb->arr[i].tag != LS_TNIL) { *k = ls_int(i + 1); *v = tb->arr[i]; return 1; }
    for (unsigned i = 0; i < tb->nsize; i++)
      if (tb->node[i].v.tag != LS_TNIL && tb->node[i].k.tag != LS_TNIL) {
        *k = tb->node[i].k; *v = tb->node[i].v; return 1;
      }
    return 0;
  }
  /* hash key: find its node */
  unsigned m = tb->nsize ? tb->nsize - 1 : 0;
  if (tb->nsize == 0)
    ls_errorraw(S, ls_str(S, "invalid key to 'next'"));
  unsigned mi = key_hash(*k) & m;
  int idx = (int)mi;
  while (1) {
    ls_TNode *nd = &tb->node[idx];
    if (nd->k.tag == LS_TNIL && nd->v.tag == LS_TNIL)
      ls_errorraw(S, ls_str(S, "invalid key to 'next'"));
    if (key_eq(nd->k, *k)) {
      for (unsigned i = (unsigned)idx + 1; i < tb->nsize; i++)
        if (tb->node[i].v.tag != LS_TNIL && tb->node[i].k.tag != LS_TNIL) {
          *k = tb->node[i].k; *v = tb->node[i].v; return 1;
        }
      return 0;
    }
    if (nd->next == 0)
      ls_errorraw(S, ls_str(S, "invalid key to 'next'"));
    idx = nd->next - 1;
  }
}

/* klua - lex.c: lexer */
#include "core.h"
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdarg.h>

typedef struct ls_Lex {
  ls_State *S;
  const char *p, *end;
  const char *chunk;      /* display chunk name (no '@') */
  int line;
  /* current token */
  int tok;
  ls_Value sem;           /* semantic value for names/strings/numbers */
  ls_Int ival; ls_Flt fval; int isint;
  int ahead;              /* lookahead token */
  ls_Value aheadsem; ls_Int aheadival; ls_Flt aheadfval; int aheadisint;
  int aheadline;
  int tokline;
  char *err;              /* set on error */
  ls_Buf buf;             /* scratch for strings */
} ls_Lex;

enum {
  TK_EOF = 0,
  TK_NAME = 256, TK_INT, TK_FLT, TK_STR,
  TK_AND, TK_BREAK, TK_DO, TK_ELSE, TK_ELSEIF, TK_END, TK_FALSE, TK_FOR,
  TK_FUNCTION, TK_GOTO, TK_IF, TK_IN, TK_LOCAL, TK_NIL, TK_NOT, TK_OR,
  TK_REPEAT, TK_RETURN, TK_THEN, TK_TRUE, TK_UNTIL, TK_WHILE,
  TK_CONCAT,    /* .. */
  TK_ELLIPSIS,  /* ... */
  TK_EQ, TK_NE, TK_LE, TK_GE, TK_SHL, TK_SHR, TK_IDIV, /* == ~= <= >= << >> // */
  TK_DBCOLON    /* :: */
};

static void lexerr(ls_Lex *L, const char *fmt, ...) {
  if (L->err) return;
  char msg[256];
  va_list ap; va_start(ap, fmt);
  vsnprintf(msg, sizeof(msg), fmt, ap);
  va_end(ap);
  char full[512];
  snprintf(full, sizeof(full), "%s:%d: %s", L->chunk, L->line, msg);
  L->err = strdup(full);
  longjmp(*(jmp_buf*)L->buf.b, 1); /* abuse: parser sets recovery point */
}

/* note: lexerr longjmps; parser installs handler. We store jmp_buf via buf.b hack;
   cleaner: parser wraps calls. We'll instead make lexer functions return error via L->err
   and parser checks. Simpler: parser sets a real jmp_buf pointer field. */

/* klua - ast.h: AST node definitions shared by parse.c and eval.c */
#ifndef KLUA_AST_H
#define KLUA_AST_H

#include "core.h"

enum {
  /* expressions */
  E_NIL, E_TRUE, E_FALSE, E_INT, E_FLT, E_STR, E_VARARG,
  E_LOCAL,      /* i1 = slot */
  E_UPVAL,      /* i1 = upvalue index */
  E_INDEX,      /* a = obj, b = key */
  E_CALL,       /* a = fn expr; list = arg exprs; i1 = 1 if tail call */
  E_METHOD,     /* a = obj; val = method name; list = args */
  E_FUNC,       /* proto = Proto* */
  E_TABLE,      /* list = array items; list2/ilist pairs: keys(list2), values via ->b? see below */
  E_BINOP,      /* i1 = op; a, b */
  E_UNOP,       /* i1 = op; a */
  E_AND, E_OR,  /* a, b */
  E_PAREN,      /* a; forces single value */

  /* statements */
  S_BLOCK,      /* list = stmts; i1 = close-from slot or -1; ilist/n2 = tbc slots */
  S_LOCAL,      /* ilist = slots, n = count; list = init exprs; val unused; i2: has tbc? per-slot attrs in ilist2 */
  S_ASSIGN,     /* list = targets, list2 = exprs */
  S_EXPR,       /* a = call/method expr */
  S_IF,         /* list = conds, list2 = blocks (n conds; n+1 or n blocks) */
  S_WHILE,      /* a = cond, b = block */
  S_REPEAT,     /* a = block, b = cond */
  S_FORNUM,     /* ilist = {varslot, ctrlslot}; a=start,b=limit,c=step; proto? block in list[0]; i3 = isint loop */
  S_FORIN,      /* ilist = var slots (n); list = explist; list2[0] = block; i2 = ctrlslot; i3 = toccloseslot(-1 none) */
  S_RETURN,     /* list = exprs */
  S_BREAK,
  S_GOTO,       /* i1 = target stmt index; b = target block node */
  S_LABEL,
  S_DO          /* a = block */
};

/* table constructor items: stored as flat list where keyed items are
   represented by E_BINOP-like marker nodes: kind==S_ASSIGN? No:
   we use E_TABLE with:
     list  = array-style value exprs (n of them)
     list2 = key exprs, and ilist unused; values for keyed items are in ->b chain? 
   Simpler: keys in list2, values in a second array stored in 'proto' cast? No.
   We store keyed items as E_KEYPAIR nodes inside 'list' after the plain items:
   E_KEYPAIR: a = key expr, b = value expr. Parser emits array items first,
   then E_KEYPAIR nodes. n counts all. */
#define E_KEYPAIR 100

struct ls_Node {
  int kind;
  int line;
  ls_Node *a, *b, *c;
  ls_Node **list; int n;
  ls_Node **list2; int n2;
  int *ilist;    /* slot lists etc. */
  int *ilist2;
  int i1, i2, i3;
  ls_Value val;  /* literal / name string */
  ls_Proto *proto;
};

ls_Node *ls_newnode(ls_State *S, int kind, int line);

#endif

