static void perr(ls_Parser *P, const char *fmt, ...) {
  char msg[512];
  va_list ap; va_start(ap, fmt);
  vsnprintf(msg, sizeof(msg), fmt, ap);
  va_end(ap);
  char full[600];
  snprintf(full, sizeof(full), "%s:%d: %s", P->chunk, P->line, msg);
  P->err = strdup(full);
  longjmp(*P->jb, 1);
}

/* ---------------- lexer ---------------- */

static int curch(ls_Parser *P) { return P->p < P->end ? (unsigned char)*P->p : -1; }
static int nextch(ls_Parser *P) { return (P->p + 1) < P->end ? (unsigned char)P->p[1] : -1; }
static int adv(ls_Parser *P) { int c = curch(P); if (c >= 0) { if (c == '\n') P->line++; P->p++; } return c; }

static void skipws(ls_Parser *P) {
  for (;;) {
    int c = curch(P);
    if (c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\v' || c == '\f') adv(P);
    else if (c == '-' && nextch(P) == '-') {
      adv(P); adv(P);
      if (curch(P) == '[') {
        /* maybe long comment */
        const char *save = P->p; int savel = P->line;
        adv(P);
        int lvl = 0;
        while (curch(P) == '=') { adv(P); lvl++; }
        if (curch(P) == '[') {
          adv(P);
          int done = 0;
          while (!done) {
            int cc = curch(P);
            if (cc < 0) perr(P, "unfinished long comment (starting at line %d) near '<eof>'", savel);
            if (cc == ']') {
              adv(P);
              int l2 = 0;
              while (curch(P) == '=') { adv(P); l2++; }
              if (l2 == lvl && curch(P) == ']') { adv(P); done = 1; }
            } else adv(P);
          }
        } else { P->p = save; P->line = savel; }
      }
      if (curch(P) == '-' && nextch(P) == '-') continue; /* was not long comment: rescan */
      /* short comment */
      while (curch(P) >= 0 && curch(P) != '\n') adv(P);
    }
    else break;
  }
}

static int check2(ls_Parser *P, const char *s) {
  if (curch(P) == s[0] && nextch(P) == s[1]) { adv(P); adv(P); return 1; }
  return 0;
}

static int read_numeral(ls_Parser *P) {
  const char *start = P->p;
  int isfloat = 0;
  if (curch(P) == '0' && (nextch(P) == 'x' || nextch(P) == 'X')) {
    adv(P); adv(P);
    while (isxdigit(curch(P))) adv(P);
    if (curch(P) == '.') { isfloat = 1; adv(P); while (isxdigit(curch(P))) adv(P); }
    if (curch(P) == 'p' || curch(P) == 'P') {
      isfloat = 1; adv(P);
      if (curch(P) == '+' || curch(P) == '-') adv(P);
      while (isdigit(curch(P))) adv(P);
    }
  } else {
    while (isdigit(curch(P))) adv(P);
    if (curch(P) == '.' && nextch(P) != '.') { isfloat = 1; adv(P); while (isdigit(curch(P))) adv(P); }
    if (curch(P) == 'e' || curch(P) == 'E') {
      isfloat = 1; adv(P);
      if (curch(P) == '+' || curch(P) == '-') adv(P);
      while (isdigit(curch(P))) adv(P);
    }
  }
  size_t n = (size_t)(P->p - start);
  if (isalnum(curch(P)) || curch(P) == '_') {
    while (isalnum(curch(P)) || curch(P) == '_') adv(P);
    perr(P, "malformed number near '%.*s%c...'", (int)n, start, curch(P) > 0 ? curch(P) : ' ');
  }
  char buf[128];
  if (n >= sizeof(buf)) perr(P, "malformed number near '%.20s...'", start);
  memcpy(buf, start, n); buf[n] = 0;
  if (!isfloat) {
    if (buf[0] == '0' && (buf[1] == 'x' || buf[1] == 'X')) {
      /* hex integer: wraps around */
      ls_Uint u = 0;
      for (const char *q = buf + 2; *q; q++) {
        int d = isdigit((unsigned char)*q) ? *q - '0' : (tolower((unsigned char)*q) - 'a' + 10);
        u = u * 16 + (ls_Uint)d;
      }
      P->ival = (ls_Int)u;
      return TK_INT;
    }
    /* decimal integer; on overflow becomes float */
    errno = 0;
    char *e;
    long long v = strtoll(buf, &e, 10);
    if (*e == 0 && errno != ERANGE) { P->ival = v; return TK_INT; }
    double d = strtod(buf, &e);
    if (*e != 0) perr(P, "malformed number near '%s'", buf);
    P->fval = d;
    return TK_FLT;
  }
  char *e;
  double d = strtod(buf, &e);
  if (*e != 0) perr(P, "malformed number near '%s'", buf);
  P->fval = d;
  return TK_FLT;
}

static int read_longstr(ls_Parser *P, int *outlevel, ls_Buf *B) {
  /* at '['; returns 1 if long bracket, else 0. On success fills B. */
  const char *save = P->p; int savel = P->line;
  adv(P);
  int lvl = 0;
  while (curch(P) == '=') { adv(P); lvl++; }
  if (curch(P) != '[') { P->p = save; P->line = savel; return 0; }
  adv(P);
  if (curch(P) == '\n') adv(P); /* skip first newline */
  for (;;) {
    int c = curch(P);
    if (c < 0) perr(P, "unfinished long string (starting at line %d) near '<eof>'", savel);
    if (c == ']') {
      adv(P);
      int l2 = 0;
      while (curch(P) == '=') { adv(P); l2++; }
      if (l2 == lvl && curch(P) == ']') { adv(P); break; }
      ls_bufaddch(B, ']');
      for (int i = 0; i < l2; i++) ls_bufaddch(B, '=');
    } else {
      ls_bufaddch(B, (char)adv(P));
    }
  }
  if (outlevel) *outlevel = lvl;
  return 1;
}

static int nexttoken(ls_Parser *P) {
  skipws(P);
  P->tokline = P->line;
  int c = curch(P);
  if (c < 0) return TK_EOF;
  if (isalpha(c) || c == '_') {
    const char *start = P->p;
    while (isalnum(curch(P)) || curch(P) == '_') adv(P);
    size_t n = (size_t)(P->p - start);
    for (const Kw *k = kws; k->name; k++)
      if (strlen(k->name) == n && memcmp(k->name, start, n) == 0) return k->tok;
    P->sem = ls_strn(P->S, start, n);
    return TK_NAME;
  }
  if (isdigit(c) || (c == '.' && isdigit(nextch(P)))) return read_numeral(P);
  switch (c) {
    case '"': case '\'': {
      int q = adv(P);
      ls_Buf B; ls_bufinit(P->S, &B);
      for (;;) {
        int cc = curch(P);
        if (cc < 0 || cc == '\n')
          perr(P, "unfinished string near '%s%.*s'", q == '"' ? "\"" : "'",
               (int)(B.n > 20 ? 20 : B.n), B.b ? B.b : "");
        if (cc == q) { adv(P); break; }
        if (cc == '\\') {
          adv(P);
          int e = curch(P);
          switch (e) {
            case 'a': ls_bufaddch(&B, '\a'); adv(P); break;
            case 'b': ls_bufaddch(&B, '\b'); adv(P); break;
            case 'f': ls_bufaddch(&B, '\f'); adv(P); break;
            case 'n': ls_bufaddch(&B, '\n'); adv(P); break;
            case 'r': ls_bufaddch(&B, '\r'); adv(P); break;
            case 't': ls_bufaddch(&B, '\t'); adv(P); break;
            case 'v': ls_bufaddch(&B, '\v'); adv(P); break;
            case '\\': ls_bufaddch(&B, '\\'); adv(P); break;
            case '"': ls_bufaddch(&B, '"'); adv(P); break;
            case '\'': ls_bufaddch(&B, '\''); adv(P); break;
            case '\n': ls_bufaddch(&B, '\n'); adv(P); break;
            case 'x': {
              adv(P);
              int v = 0, nd = 0;
              while (nd < 2 && isxdigit(curch(P))) {
                int d = isdigit((unsigned char)curch(P)) ? curch(P)-'0' : tolower((unsigned char)curch(P))-'a'+10;
                v = v*16 + d; adv(P); nd++;
              }
              if (nd == 0) perr(P, "hexadecimal digit expected near '\\x%c'", curch(P)>0?curch(P):' ');
              ls_bufaddch(&B, (char)v);
              break;
            }
            case 'z': {
              adv(P);
              while (curch(P) >= 0 && isspace(curch(P))) adv(P);
              break;
            }
            case 'u': {
              adv(P);
              if (curch(P) != '{') perr(P, "missing '{' in \\u{xxxx}");
              adv(P);
              unsigned long v = 0; int nd = 0;
              while (isxdigit(curch(P))) {
                int d = isdigit((unsigned char)curch(P)) ? curch(P)-'0' : tolower((unsigned char)curch(P))-'a'+10;
                if (v > (0x7FFFFFFFUL >> 4)) perr(P, "UTF-8 value too large");
                v = v*16 + (unsigned long)d; adv(P); nd++;
              }
              if (nd == 0) perr(P, "hexadecimal digit expected");
              if (curch(P) != '}') perr(P, "missing '}' in \\u{xxxx}");
              adv(P);
              if (v > 0x7FFFFFFFUL) perr(P, "UTF-8 value too large");
              /* encode UTF-8 */
              char tmp[8]; int tn = 0;
              if (v < 0x80) tmp[tn++] = (char)v;
              else if (v < 0x800) {
                tmp[tn++] = (char)(0xC0 | (v >> 6));
                tmp[tn++] = (char)(0x80 | (v & 0x3F));
              } else if (v < 0x10000) {
                tmp[tn++] = (char)(0xE0 | (v >> 12));
                tmp[tn++] = (char)(0x80 | ((v >> 6) & 0x3F));
                tmp[tn++] = (char)(0x80 | (v & 0x3F));
              } else if (v < 0x200000) {
                tmp[tn++] = (char)(0xF0 | (v >> 18));
                tmp[tn++] = (char)(0x80 | ((v >> 12) & 0x3F));
                tmp[tn++] = (char)(0x80 | ((v >> 6) & 0x3F));
                tmp[tn++] = (char)(0x80 | (v & 0x3F));
              } else if (v < 0x4000000) {
                tmp[tn++] = (char)(0xF8 | (v >> 24));
                tmp[tn++] = (char)(0x80 | ((v >> 18) & 0x3F));
                tmp[tn++] = (char)(0x80 | ((v >> 12) & 0x3F));
                tmp[tn++] = (char)(0x80 | ((v >> 6) & 0x3F));
                tmp[tn++] = (char)(0x80 | (v & 0x3F));
              } else {
                tmp[tn++] = (char)(0xFC | (v >> 30));
                tmp[tn++] = (char)(0x80 | ((v >> 24) & 0x3F));
                tmp[tn++] = (char)(0x80 | ((v >> 18) & 0x3F));
                tmp[tn++] = (char)(0x80 | ((v >> 12) & 0x3F));
                tmp[tn++] = (char)(0x80 | ((v >> 6) & 0x3F));
                tmp[tn++] = (char)(0x80 | (v & 0x3F));
              }
              ls_bufadd(&B, tmp, (size_t)tn);
              break;
            }
            default: {
              if (isdigit(e)) {
                int v = 0, nd = 0;
                while (nd < 3 && isdigit(curch(P))) { v = v*10 + (curch(P)-'0'); adv(P); nd++; }
                if (v > 255) perr(P, "decimal escape too large near '\\%d'", v);
                ls_bufaddch(&B, (char)v);
              } else if (e < 0) {
                perr(P, "unfinished string near '%s'", q == '"' ? "\"" : "'");
              } else {
                perr(P, "invalid escape sequence '\\%c'", e);
              }
            }
          }
        } else {
          ls_bufaddch(&B, (char)adv(P));
        }
      }
      P->sem = ls_bufresult(&B);
      return TK_STR;
    }
    case '[': {
      ls_Buf B; ls_bufinit(P->S, &B);
      if (read_longstr(P, NULL, &B)) { P->sem = ls_bufresult(&B); return TK_STR; }
      adv(P);
      return '[';
    }
    case '=': adv(P); if (curch(P) == '=') { adv(P); return TK_EQ; } return '=';
    case '~': adv(P); if (curch(P) == '=') { adv(P); return TK_NE; } return '~';
    case '<': adv(P);
      if (curch(P) == '=') { adv(P); return TK_LE; }
      if (curch(P) == '<') { adv(P); return TK_SHL; }
      return '<';
    case '>': adv(P);
      if (curch(P) == '=') { adv(P); return TK_GE; }
      if (curch(P) == '>') { adv(P); return TK_SHR; }
      return '>';
    case '/': adv(P); if (curch(P) == '/') { adv(P); return TK_IDIV; } return '/';
    case '.': adv(P);
      if (curch(P) == '.') {
        adv(P);
        if (curch(P) == '.') { adv(P); return TK_ELLIPSIS; }
        return TK_CONCAT;
      }
      return '.';
    case ':': adv(P); if (curch(P) == ':') { adv(P); return TK_DBCOLON; } return ':';
    default: adv(P); return c;
  }
}

static void nextok(ls_Parser *P) { P->tok = nexttoken(P); }

static const char *toktext(ls_Parser *P, int tok, char *buf, size_t n) {
  switch (tok) {
    case TK_EOF: return "<eof>";
    case TK_NAME: snprintf(buf, n, "%s", ls_vstr(P->sem)); return buf;
    case TK_STR: {
      size_t l = ls_vstrlen(P->sem);
      if (l > 20) l = 20;
      snprintf(buf, n, "\"%.*s\"", (int)l, ls_vstr(P->sem));
      return buf;
    }
    case TK_INT: snprintf(buf, n, "%lld", (long long)P->ival); return buf;
    case TK_FLT: { ls_fmtflt(buf, P->fval); return buf; }
    case TK_AND: return "and"; case TK_BREAK: return "break"; case TK_DO: return "do";
    case TK_ELSE: return "else"; case TK_ELSEIF: return "elseif"; case TK_END: return "end";
    case TK_FALSE: return "false"; case TK_FOR: return "for"; case TK_FUNCTION: return "function";
    case TK_GOTO: return "goto"; case TK_IF: return "if"; case TK_IN: return "in";
    case TK_LOCAL: return "local"; case TK_NIL: return "nil"; case TK_NOT: return "not";
    case TK_OR: return "or"; case TK_REPEAT: return "repeat"; case TK_RETURN: return "return";
    case TK_THEN: return "then"; case TK_TRUE: return "true"; case TK_UNTIL: return "until";
    case TK_WHILE: return "while";
    case TK_CONCAT: return ".."; case TK_ELLIPSIS: return "..."; case TK_EQ: return "==";
    case TK_NE: return "~="; case TK_LE: return "<="; case TK_GE: return ">=";
    case TK_SHL: return "<<"; case TK_SHR: return ">>"; case TK_IDIV: return "//";
    case TK_DBCOLON: return "::";
    default:
      if (tok < 256) { buf[0] = (char)tok; buf[1] = 0; return buf; }
      return "?";
  }
}

static void errnear(ls_Parser *P, const char *msg) {
  char b[64];
  perr(P, "%s near '%s'", msg, toktext(P, P->tok, b, sizeof(b)));
}

static void expect(ls_Parser *P, int tok, const char *what) {
  if (P->tok != tok) {
    char b[64];
    perr(P, "'%s' expected near '%s'", what, toktext(P, P->tok, b, sizeof(b)));
  }
  nextok(P);
}

static int accept(ls_Parser *P, int tok) {
  if (P->tok == tok) { nextok(P); return 1; }
  return 0;
}

/* ---------------- parser: nodes ---------------- */

ls_Node *ls_newnode(ls_State *S, int kind, int line) {
  (void)S;
  ls_Node *nd = calloc(1, sizeof(ls_Node));
  nd->kind = kind; nd->line = line;
  return nd;
}

static ls_Node *mkn(ls_Parser *P, int kind) { return ls_newnode(P->S, kind, P->tokline); }

static void nodelist_add(ls_Parser *P, ls_Node ***list, int *n, ls_Node *nd) {
  (void)P;
  *list = realloc(*list, sizeof(ls_Node*) * (*n + 1));
  (*list)[(*n)++] = nd;
}

/* ---------------- function state / scopes ---------------- */

static ls_FState *newfs(ls_Parser *P, ls_FState *parent, int isvararg) {
  ls_FState *f = calloc(1, sizeof(ls_FState));
  f->parent = parent;
  f->p = calloc(1, sizeof(ls_Proto));
  f->p->chunk = strdup(P->chunk);
  f->isvararg = isvararg;
  return f;
}

static int addlocal(ls_Parser *P, ls_FState *f, const char *name, int attrib, int line) {
  if (f->nloc == f->caploc) {
    f->caploc = f->caploc ? f->caploc * 2 : 16;
    f->locals = realloc(f->locals, f->caploc * sizeof(ls_Local));
  }
  int slot = f->nextslot++;
  f->locals[f->nloc].name = strdup(name);
  f->locals[f->nloc].slot = slot;
  f->locals[f->nloc].attrib = attrib;
  f->locals[f->nloc].captured = 0;
  f->locals[f->nloc].line = line;
  f->nloc++;
  return slot;
}

/* find local by name in function (active locals = all in f->locals list,
   since we never reuse slots; scope removal pops entries) */
static int findlocal(ls_FState *f, const char *name) {
  for (int i = f->nloc - 1; i >= 0; i--)
    if (strcmp(f->locals[i].name, name) == 0) return i;
  return -1;
}

static int findupval(ls_FState *f, const char *name) {
  for (int i = 0; i < f->nups; i++)
    if (strcmp(ls_vstr(f->upnames[i]), name) == 0) return i;
  return -1;
}

static int addupval(ls_Parser *P, ls_FState *f, const char *name, int inslot, int upidx) {
  if (f->nups == f->capups) {
    f->capups = f->capups ? f->capups * 2 : 8;
    f->upnames = realloc(f->upnames, f->capups * sizeof(ls_Value));
    f->upinslot = realloc(f->upinslot, f->capups * sizeof(int));
    f->upupidx = realloc(f->upupidx, f->capups * sizeof(int));
  }
  f->upnames[f->nups] = ls_str(P->S, name);
  f->upinslot[f->nups] = inslot;
  f->upupidx[f->nups] = upidx;
  return f->nups++;
}

/* resolve name as local or upvalue; returns node */
static ls_Node *resolvename(ls_Parser *P, ls_FState *f, const char *name, int line) {
  int li = findlocal(f, name);
  if (li >= 0) {
    ls_Node *nd = ls_newnode(P->S, E_LOCAL, line);
    nd->i1 = f->locals[li].slot;
    return nd;
  }
  int ui = findupval(f, name);
  if (ui >= 0) {
    ls_Node *nd = ls_newnode(P->S, E_UPVAL, line);
    nd->i1 = ui;
    return nd;
  }
  /* search parent */
  if (f->parent) {
    ls_FState *par = f->parent;
    int pli = findlocal(par, name);
    if (pli >= 0) {
      par->locals[pli].captured = 1;
      int idx = addupval(P, f, name, par->locals[pli].slot, -1);
      ls_Node *nd = ls_newnode(P->S, E_UPVAL, line);
      nd->i1 = idx;
      return nd;
    }
    if (par->parent) {
      ls_Node *inner = resolvename(P, par, name, line);
      if (inner && inner->kind == E_UPVAL) {
        int idx = addupval(P, f, name, -1, inner->i1);
        ls_Node *nd = ls_newnode(P->S, E_UPVAL, line);
        nd->i1 = idx;
        return nd;
      }
      if (inner) { /* resolved as parent's _ENV local? shouldn't happen */
        return inner;
      }
    }
  }
  /* global: index into _ENV */
  ls_Node *env = ls_newnode(P->S, 0, line);
  {
    /* _ENV is always resolvable: main chunk has it as local slot 0;
       nested functions as upvalue (add chain) */
    ls_FState *g = f;
    int ui2 = findupval(g, "_ENV");
    if (ui2 >= 0) { env->kind = E_UPVAL; env->i1 = ui2; }
    else {
      int li2 = findlocal(g, "_ENV");
      if (li2 >= 0) { env->kind = E_LOCAL; env->i1 = g->locals[li2].slot; }
      else if (g->parent) {
        ls_Node *r = resolvename(P, g->parent, "_ENV", line);
        if (r->kind == E_LOCAL) {
          g->parent->locals[findlocal(g->parent, "_ENV")].captured = 1;
          int idx = addupval(P, g, "_ENV", r->i1, -1);
          env->kind = E_UPVAL; env->i1 = idx;
        } else {
          int idx = addupval(P, g, "_ENV", -1, r->i1);
          env->kind = E_UPVAL; env->i1 = idx;
        }
      } else {
        perr(P, "internal: no _ENV");
      }
    }
  }
  ls_Node *nd = ls_newnode(P->S, E_INDEX, line);
  nd->a = env;
  nd->b = ls_newnode(P->S, E_STR, line);
  nd->b->val = ls_str(P->S, name);
  return nd;
}

/* ---------------- blocks ---------------- */

static ls_BlkInfo *enterblock(ls_Parser *P, ls_FState *f, int isloop) {
  ls_BlkInfo *b = calloc(1, sizeof(ls_BlkInfo));
  b->parent = f->blks;
  b->nactvar = f->nloc;
  b->isloop = isloop;
  b->node = mkn(P, S_BLOCK);
  b->node->i1 = -1; /* closefrom */
  b->node->i2 = 0;
  f->blks = b;
  return b;
}

/* close a block: check pending gotos, set closefrom */
static void leaveblock(ls_Parser *P, ls_FState *f, ls_BlkInfo *b) {
  /* resolve pending gotos in this block: any goto still unresolved is an error */
  for (ls_Goto *g = b->gotos; g; g = g->next) {
    /* was it resolved? we mark node->b when resolved */
    if (!g->node->b) {
      char b1[64];
      snprintf(b1, sizeof b1, "%s", g->name);
      int l = g->line;
      P->err = NULL;
      /* error at goto's line */
      char full[600];
      snprintf(full, sizeof(full), "%s:%d: no visible label '%s' for <goto>", P->chunk, l, b1);
      P->err = strdup(full);
      longjmp(*P->jb, 1);
    }
  }
  /* compute closefrom: min slot of captured locals declared in this block */
  int closefrom = -1;
  for (int i = b->nactvar; i < f->nloc; i++)
    if (f->locals[i].captured) {
      int s = f->locals[i].slot;
      if (closefrom < 0 || s < closefrom) closefrom = s;
    }
  b->node->i1 = closefrom;
  /* pop locals declared in block */
  f->nloc = b->nactvar;
  f->blks = b->parent;
}

/* ---------------- expressions ---------------- */

static ls_Node *parse_expr(ls_Parser *P);
static ls_Node *parse_subexpr(ls_Parser *P, int limit);
static ls_Node *parse_block(ls_Parser *P);

static ls_Node *parse_string_expr(ls_Parser *P) {
  ls_Node *nd = mkn(P, E_STR);
  nd->val = P->sem;
  nextok(P);
  return nd;
}

static ls_Node *parse_funcbody(ls_Parser *P, int line, int ismethod) {
  ls_FState *f = newfs(P, P->fs, 0);
  f->p->line = line;
  ls_FState *outer = P->fs;
  P->fs = f;
  expect(P, '(', "(");
  if (ismethod) addlocal(P, f, "self", 0, line);
  /* params */
  if (P->tok != ')') {
    for (;;) {
      if (P->tok == TK_NAME) {
        addlocal(P, f, ls_vstr(P->sem), 0, P->tokline);
        nextok(P);
      } else if (P->tok == TK_ELLIPSIS) {
        f->isvararg = 1;
        nextok(P);
        break;
      } else errnear(P, "<name> expected");
      if (!accept(P, ',')) break;
    }
  }
  expect(P, ')', ")");
  f->p->nparams = f->nloc;
  ls_Node *body = parse_block(P);
  /* body closefrom already computed by parse_block's leaveblock? parse_block
     creates its own block; function body block: we need leaveblock with
     function scope. We entered newfs but no blkinfo. Wrap: */
  f->p->body = body;
  f->p->nslots = f->nextslot;
  f->p->nups = f->nups;
  f->p->upinslot = f->upinslot;
  f->p->upupidx = f->upupidx;
  f->p->upnames = malloc(sizeof(char*) * (f->nups + 1));
  for (int i = 0; i < f->nups; i++) f->p->upnames[i] = strdup(ls_vstr(f->upnames[i]));
  f->p->nparams = f->nparams_total = 0; /* set below */
  /* record local names for error messages */
  f->p->nslots = f->nextslot;
  f->p->locnames = calloc(f->nextslot + 1, sizeof(char*));
  f->p->locline = calloc(f->nextslot + 1, sizeof(int));
  for (int i = 0; i < f->nloc_total; i++) { }
  expect(P, TK_END, "end");
  f->p->lastline = P->tokline;
  ls_Node *nd = ls_newnode(P->S, E_FUNC, line);
  nd->proto = f->p;
  P->fs = outer;
  return nd;
}

