/* ---------------- expressions (continued) ---------------- */

static ls_Node *parse_explist(ls_Parser *P, int *n) {
  /* returns head of array stored in a temp node list; caller copies */
  ls_Node *holder = mkn(P, S_BLOCK);
  ls_Node *e = parse_expr(P);
  nodelist_add(P, &holder->list, &holder->n, e);
  while (accept(P, ',')) {
    e = parse_expr(P);
    nodelist_add(P, &holder->list, &holder->n, e);
  }
  *n = holder->n;
  return (ls_Node *)holder;
}

static ls_Node *parse_primary(ls_Parser *P) {
  if (P->tok == '(') {
    int line = P->tokline;
    nextok(P);
    ls_Node *e = parse_expr(P);
    expect(P, ')', ")");
    ls_Node *nd = ls_newnode(P->S, E_PAREN, line);
    nd->a = e;
    return nd;
  }
  if (P->tok == TK_NAME) {
    ls_Node *nd = resolvename(P, P->fs, ls_vstr(P->sem), P->tokline);
    nextok(P);
    return nd;
  }
  errnear(P, "unexpected symbol");
  return NULL;
}

static ls_Node *parse_tablector(ls_Parser *P);
static ls_Node *parse_callargs(ls_Parser *P, ls_Node *fn, int line) {
  ls_Node *call = ls_newnode(P->S, E_CALL, line);
  call->a = fn;
  if (P->tok == '(') {
    nextok(P);
    if (P->tok != ')') {
      int n;
      ls_Node *h = parse_explist(P, &n);
      call->list = h->list; call->n = n;
    }
    expect(P, ')', ")");
  } else if (P->tok == TK_STR) {
    nodelist_add(P, &call->list, &call->n, parse_string_expr(P));
  } else if (P->tok == '{') {
    nodelist_add(P, &call->list, &call->n, parse_tablector(P));
  } else errnear(P, "function arguments expected");
  return call;
}

static ls_Node *parse_suffixed(ls_Parser *P) {
  ls_Node *e = parse_primary(P);
  for (;;) {
    int line = P->tokline;
    if (P->tok == '.') {
      nextok(P);
      if (P->tok != TK_NAME) errnear(P, "<name> expected");
      ls_Node *nd = ls_newnode(P->S, E_INDEX, line);
      nd->a = e;
      nd->b = ls_newnode(P->S, E_STR, line);
      nd->b->val = P->sem;
      nextok(P);
      e = nd;
    } else if (P->tok == '[') {
      nextok(P);
      ls_Node *k = parse_expr(P);
      expect(P, ']', "]");
      ls_Node *nd = ls_newnode(P->S, E_INDEX, line);
      nd->a = e; nd->b = k;
      e = nd;
    } else if (P->tok == ':') {
      nextok(P);
      if (P->tok != TK_NAME) errnear(P, "<name> expected");
      ls_Node *nd = ls_newnode(P->S, E_METHOD, line);
      nd->a = e;
      nd->val = P->sem;
      nextok(P);
      /* args */
      if (P->tok == '(') {
        nextok(P);
        if (P->tok != ')') {
          int n;
          ls_Node *h = parse_explist(P, &n);
          nd->list = h->list; nd->n = n;
        }
        expect(P, ')', ")");
      } else if (P->tok == TK_STR) {
        nodelist_add(P, &nd->list, &nd->n, parse_string_expr(P));
      } else if (P->tok == '{') {
        nodelist_add(P, &nd->list, &nd->n, parse_tablector(P));
      } else errnear(P, "function arguments expected");
      e = nd;
    } else if (P->tok == '(' || P->tok == TK_STR || P->tok == '{') {
      e = parse_callargs(P, e, line);
    } else return e;
  }
}

static ls_Node *parse_simpleexp(ls_Parser *P) {
  int line = P->tokline;
  ls_Node *nd;
  switch (P->tok) {
    case TK_INT: nd = mkn(P, E_INT); nd->val = ls_int(P->ival); nextok(P); return nd;
    case TK_FLT: nd = mkn(P, E_FLT); nd->val = ls_flt(P->fval); nextok(P); return nd;
    case TK_STR: return parse_string_expr(P);
    case TK_NIL: nextok(P); return ls_newnode(P->S, E_NIL, line);
    case TK_TRUE: nextok(P); return ls_newnode(P->S, E_TRUE, line);
    case TK_FALSE: nextok(P); return ls_newnode(P->S, E_FALSE, line);
    case TK_ELLIPSIS: {
      if (!P->fs->isvararg) {
        perr(P, "%s:%d: cannot use '...' outside a vararg function near '...'", "", 0);
      }
      nextok(P);
      return ls_newnode(P->S, E_VARARG, line);
    }
    case '{': return parse_tablector(P);
    case TK_FUNCTION: {
      nextok(P);
      return parse_funcbody(P, line, 0);
    }
    default:
      return parse_suffixed(P);
  }
}

/* binary operator priorities */
static int binop_pri(int tok, int *right) {
  *right = 0;
  switch (tok) {
    case TK_OR: return 1;
    case TK_AND: return 2;
    case '<': case '>': case TK_LE: case TK_GE: case TK_NE: case TK_EQ: return 3;
    case '|': return 4;
    case '~': return 5;
    case '&': return 6;
    case TK_SHL: case TK_SHR: return 7;
    case TK_CONCAT: *right = 1; return 9;
    case '+': case '-': return 10;
    case '*': case '/': case TK_IDIV: case '%': return 11;
    case '^': *right = 1; return 14;
    default: return 0;
  }
}
#define UNARY_PRI 12

static int tok2binop(int tok) {
  switch (tok) {
    case '+': return LS_OPADD; case '-': return LS_OPSUB; case '*': return LS_OPMUL;
    case '%': return LS_OPMOD; case '^': return LS_OPPOW; case '/': return LS_OPDIV;
    case TK_IDIV: return LS_OPIDIV; case '&': return LS_OPBAND; case '|': return LS_OPBOR;
    case '~': return LS_OPBXOR; case TK_SHL: return LS_OPSHL; case TK_SHR: return LS_OPSHR;
    case TK_EQ: return LS_OPEQ; case TK_NE: return LS_OPEQ + 100; /* NE marker */
    case '<': return LS_OPLT; case TK_LE: return LS_OPLE;
    case '>': return LS_OPLT + 100; case TK_GE: return LS_OPLE + 100;
    case TK_CONCAT: return 300;
    case TK_AND: return 301; case TK_OR: return 302;
  }
  return -1;
}

static ls_Node *parse_subexpr(ls_Parser *P, int limit) {
  ls_Node *left;
  int line = P->tokline;
  if (P->tok == TK_NOT || P->tok == '-' || P->tok == '#' || P->tok == '~') {
    int op = P->tok;
    nextok(P);
    ls_Node *e = parse_subexpr(P, UNARY_PRI);
    ls_Node *nd = ls_newnode(P->S, E_UNOP, line);
    nd->i1 = (op == TK_NOT) ? 400 : (op == '-') ? LS_OPUNM : (op == '#') ? 401 : LS_OPBNOT;
    nd->a = e;
    left = nd;
  } else {
    left = parse_simpleexp(P);
  }
  int right;
  int pri;
  while ((pri = binop_pri(P->tok, &right)) > limit) {
    int op = P->tok;
    int opline = P->tokline;
    nextok(P);
    ls_Node *r = parse_subexpr(P, right ? pri - 1 : pri);
    ls_Node *nd;
    int bop = tok2binop(op);
    if (bop == 301) { nd = ls_newnode(P->S, E_AND, opline); }
    else if (bop == 302) { nd = ls_newnode(P->S, E_OR, opline); }
    else {
      nd = ls_newnode(P->S, E_BINOP, opline);
      nd->i1 = bop;
    }
    nd->a = left; nd->b = r;
    left = nd;
  }
  return left;
}

static ls_Node *parse_expr(ls_Parser *P) { return parse_subexpr(P, 0); }

static ls_Node *parse_tablector(ls_Parser *P) {
  int line = P->tokline;
  expect(P, '{', "{");
  ls_Node *nd = ls_newnode(P->S, E_TABLE, line);
  for (;;) {
    if (P->tok == '}') break;
    int line2 = P->tokline;
    if (P->tok == '[') {
      nextok(P);
      ls_Node *k = parse_expr(P);
      expect(P, ']', "]");
      expect(P, '=', "=");
      ls_Node *v = parse_expr(P);
      ls_Node *pair = ls_newnode(P->S, E_KEYPAIR, line2);
      pair->a = k; pair->b = v;
      nodelist_add(P, &nd->list, &nd->n, pair);
    } else if (P->tok == TK_NAME) {
      /* could be name = expr or expression starting with name */
      /* need lookahead: save state */
      const char *savep = P->p; int saveline = P->line;
      int savetok = P->tok; ls_Value savesem = P->sem; int savetokline = P->tokline;
      ls_Int saveival = P->ival; ls_Flt savefval = P->fval;
      nextok(P);
      if (P->tok == '=') {
        nextok(P);
        ls_Node *v = parse_expr(P);
        ls_Node *pair = ls_newnode(P->S, E_KEYPAIR, line2);
        pair->a = ls_newnode(P->S, E_STR, line2);
        pair->a->val = savesem;
        pair->b = v;
        nodelist_add(P, &nd->list, &nd->n, pair);
      } else {
        /* restore and parse as expression */
        P->p = savep; P->line = saveline;
        P->tok = savetok; P->sem = savesem; P->tokline = savetokline;
        P->ival = saveival; P->fval = savefval;
        nodelist_add(P, &nd->list, &nd->n, parse_expr(P));
      }
    } else {
      nodelist_add(P, &nd->list, &nd->n, parse_expr(P));
    }
    if (!accept(P, ',') && !accept(P, ';')) break;
  }
  expect(P, '}', "}");
  return nd;
}

/* ---------------- statements ---------------- */

static ls_Node *parse_stat(ls_Parser *P);

static int isblockfollow(ls_Parser *P) {
  return P->tok == TK_EOF || P->tok == TK_END || P->tok == TK_ELSE ||
         P->tok == TK_ELSEIF || P->tok == TK_UNTIL;
}

static void check_goto_locals(ls_Parser *P, ls_FState *f, ls_Goto *g, ls_Label *l) {
  if (l->nactvar < g->nactvar) {
    /* fine: jumping backward, locals leave scope */
  } else if (l->nactvar > g->nactvar) {
    /* jumping into scope of local f->locals[g->nactvar] */
    const char *nm = "?";
    for (int i = 0; i < f->nloc; i++)
      if (f->locals[i].slot >= 0 && i == g->nactvar) { nm = f->locals[i].name; break; }
    char full[600];
    snprintf(full, sizeof(full), "%s:%d: <goto %s> at line %d jumps into the scope of local '%s'",
             P->chunk, l->line, l->name, g->line, nm);
    P->err = strdup(full);
    longjmp(*P->jb, 1);
  }
}

static void addlabel(ls_Parser *P, ls_FState *f, ls_BlkInfo *b, const char *name, int line, int stmtidx) {
  /* check duplicate in this block */
  for (ls_Label *l = b->labels; l; l = l->next)
    if (strcmp(l->name, name) == 0) {
      char full[600];
      snprintf(full, sizeof(full), "%s:%d: label '%s' already defined on line %d",
               P->chunk, line, name, l->line);
      P->err = strdup(full);
      longjmp(*P->jb, 1);
    }
  ls_Label *l = calloc(1, sizeof(ls_Label));
  l->name = strdup(name); l->line = line; l->nactvar = f->nloc;
  l->block = stmtidx;
  l->next = b->labels; b->labels = l;
  /* resolve pending gotos in this block */
  ls_Goto *prev = NULL, *g = b->gotos;
  while (g) {
    ls_Goto *nx = g->next;
    if (strcmp(g->name, name) == 0 && g->nactvar == f->nloc) {
      g->node->b = b->node;
      g->node->i1 = stmtidx;
      if (prev) prev->next = nx; else b->gotos = nx;
    } else if (strcmp(g->name, name) == 0) {
      check_goto_locals(P, f, g, l);
      g->node->b = b->node;
      g->node->i1 = stmtidx;
      if (prev) prev->next = nx; else b->gotos = nx;
    } else prev = g;
    g = nx;
  }
}

static ls_Node *parse_block(ls_Parser *P) {
  ls_FState *f = P->fs;
  ls_BlkInfo *b = enterblock(P, f, 0);
  while (!isblockfollow(P)) {
    if (P->tok == TK_RETURN) {
      ls_Node *st = parse_stat(P);
      nodelist_add(P, &b->node->list, &b->node->n, st);
      break;
    }
    ls_Node *st = parse_stat(P);
    if (st) nodelist_add(P, &b->node->list, &b->node->n, st);
  }
  /* move unresolved gotos handling is done in leaveblock2 below */
  ls_BlkInfo *cur = f->blks;
  (void)cur;
  /* resolve "label at end of block" gotos, else propagate to parent */
  for (ls_Goto *g = b->gotos; g; g = g->next) {
    if (g->node->b) continue;
    /* find label in this block with same name at last position */
    for (ls_Label *l = b->labels; l; l = l->next) {
      if (strcmp(l->name, g->name) == 0) {
        /* is it last statement (ignoring other labels)? */
        int last = 1;
        for (int i = l->block + 1; i < b->node->n; i++)
          if (b->node->list[i]->kind != S_LABEL) { last = 0; break; }
        if (last) {
          g->node->b = b->node;
          g->node->i1 = b->node->n; /* jump to end of block */
        }
      }
    }
    if (!g->node->b && b->parent) {
      /* propagate */
      g->next = b->parent->gotos;
      b->parent->gotos = g;
      /* keep it in b->gotos too would double-free; mark resolved-by-move */
      /* simpler: rebuild list below */
    }
  }
  /* rebuild goto list without propagated ones */
  if (b->parent) {
    ls_Goto *keep = NULL;
    ls_Goto *g = b->gotos;
    /* we appended moved ones to parent already; but they are still in b list.
       Instead of the above mess: reconstruct. */
    (void)keep; (void)g;
  }
  leaveblock(P, f, b);
  return b->node;
}

static ls_Node *parse_if(ls_Parser *P) {
  int line = P->tokline;
  nextok(P); /* if */
  ls_Node *nd = ls_newnode(P->S, S_IF, line);
  ls_Node *cond = parse_expr(P);
  expect(P, TK_THEN, "then");
  nodelist_add(P, &nd->list, &nd->n, cond);
  nodelist_add(P, &nd->list2, &nd->n2, parse_block(P));
  while (P->tok == TK_ELSEIF) {
    nextok(P);
    cond = parse_expr(P);
    expect(P, TK_THEN, "then");
    nodelist_add(P, &nd->list, &nd->n, cond);
    nodelist_add(P, &nd->list2, &nd->n2, parse_block(P));
  }
  if (P->tok == TK_ELSE) {
    nextok(P);
    nodelist_add(P, &nd->list2, &nd->n2, parse_block(P));
  }
  expect(P, TK_END, "end");
  return nd;
}

static ls_Node *parse_while(ls_Parser *P) {
  int line = P->tokline;
  nextok(P);
  ls_Node *cond = parse_expr(P);
  expect(P, TK_DO, "do");
  ls_FState *f = P->fs;
  ls_BlkInfo *b = enterblock(P, f, 1);
  while (!isblockfollow(P)) {
    if (P->tok == TK_RETURN) { nodelist_add(P, &b->node->list, &b->node->n, parse_stat(P)); break; }
    ls_Node *st = parse_stat(P);
    if (st) nodelist_add(P, &b->node->list, &b->node->n, st);
  }
  leaveblock(P, f, b);
  expect(P, TK_END, "end");
  ls_Node *nd = ls_newnode(P->S, S_WHILE, line);
  nd->a = cond; nd->b = b->node;
  return nd;
}

static ls_Node *parse_repeat(ls_Parser *P) {
  int line = P->tokline;
  nextok(P);
  ls_FState *f = P->fs;
  ls_BlkInfo *b = enterblock(P, f, 1);
  while (!isblockfollow(P)) {
    if (P->tok == TK_RETURN) { nodelist_add(P, &b->node->list, &b->node->n, parse_stat(P)); break; }
    ls_Node *st = parse_stat(P);
    if (st) nodelist_add(P, &b->node->list, &b->node->n, st);
  }
  expect(P, TK_UNTIL, "until");
  ls_Node *cond = parse_expr(P); /* still in block scope */
  leaveblock(P, f, b);
  ls_Node *nd = ls_newnode(P->S, S_REPEAT, line);
  nd->a = b->node; nd->b = cond;
  return nd;
}

static int parse_attrib(ls_Parser *P) {
  if (accept(P, '<')) {
    if (P->tok != TK_NAME) errnear(P, "<name> expected");
    const char *nm = ls_vstr(P->sem);
    int attr;
    if (strcmp(nm, "const") == 0) attr = 1;
    else if (strcmp(nm, "close") == 0) attr = 2;
    else perr(P, "unknown attribute '%s'", nm);
    nextok(P);
    expect(P, '>', ">");
    return attr;
  }
  return 0;
}

static ls_Node *parse_local(ls_Parser *P) {
  int line = P->tokline;
  nextok(P); /* local */
  ls_FState *f = P->fs;
  if (P->tok == TK_FUNCTION) {
    nextok(P);
    if (P->tok != TK_NAME) errnear(P, "<name> expected");
    char *nm = strdup(ls_vstr(P->sem));
    int slot = addlocal(P, f, nm, 0, P->tokline);
    nextok(P);
    ls_Node *fn = parse_funcbody(P, line, 0);
    ls_Node *nd = ls_newnode(P->S, S_LOCAL, line);
    nd->ilist = malloc(sizeof(int)); nd->ilist[0] = slot; nd->i1 = 1;
    nd->ilist2 = calloc(1, sizeof(int));
    nodelist_add(P, &nd->list, &nd->n, fn);
    free(nm);
    return nd;
  }
  /* namelist with attribs */
  int slots[64], attrs[64];
  int nv = 0;
  for (;;) {
    if (P->tok != TK_NAME) errnear(P, "<name> expected");
    char *nm = strdup(ls_vstr(P->sem));
    int l2 = P->tokline;
    nextok(P);
    int attr = parse_attrib(P);
    if (attr == 2 && nv > 0) {
      /* only one close per list allowed; lua errors 'multiple to-be-closed variables' */
    }
    slots[nv] = addlocal(P, f, nm, attr, l2);
    attrs[nv] = attr;
    nv++;
    free(nm);
    if (!accept(P, ',')) break;
  }
  int nclose = 0;
  for (int i = 0; i < nv; i++) if (attrs[i] == 2) nclose++;
  if (nclose > 1) perr(P, "multiple to-be-closed variables in local list");
  ls_Node *nd = ls_newnode(P->S, S_LOCAL, line);
  nd->ilist = malloc(sizeof(int) * nv);
  nd->ilist2 = malloc(sizeof(int) * nv);
  memcpy(nd->ilist, slots, sizeof(int) * nv);
  memcpy(nd->ilist2, attrs, sizeof(int) * nv);
  nd->i1 = nv;
  if (accept(P, '=')) {
    int n;
    ls_Node *h = parse_explist(P, &n);
    nd->list = h->list; nd->n = n;
  }
  return nd;
}

static ls_Node *parse_funcname(ls_Parser *P, int *ismethod, char **lastname, int *nameline) {
  /* returns expr for the function "container"; sets lastname */
  if (P->tok != TK_NAME) errnear(P, "<name> expected");
  ls_Node *e = resolvename(P, P->fs, ls_vstr(P->sem), P->tokline);
  *lastname = strdup(ls_vstr(P->sem));
  *nameline = P->tokline;
  nextok(P);
  while (P->tok == '.') {
    int line = P->tokline;
    nextok(P);
    if (P->tok != TK_NAME) errnear(P, "<name> expected");
    ls_Node *nd = ls_newnode(P->S, E_INDEX, line);
    nd->a = e;
    nd->b = ls_newnode(P->S, E_STR, line);
    nd->b->val = P->sem;
    free(*lastname); *lastname = strdup(ls_vstr(P->sem)); *nameline = line;
    nextok(P);
    e = nd;
  }
  if (P->tok == ':') {
    int line = P->tokline;
    nextok(P);
    if (P->tok != TK_NAME) errnear(P, "<name> expected");
    ls_Node *nd = ls_newnode(P->S, E_INDEX, line);
    nd->a = e;
    nd->b = ls_newnode(P->S, E_STR, line);
    nd->b->val = P->sem;
    free(*lastname); *lastname = strdup(ls_vstr(P->sem)); *nameline = line;
    nextok(P);
    e = nd;
    *ismethod = 1;
  }
  return e;
}

static ls_Node *parse_for(ls_Parser *P) {
  int line = P->tokline;
  nextok(P); /* for */
  ls_FState *f = P->fs;
  if (P->tok != TK_NAME) errnear(P, "<name> expected");
  char *first = strdup(ls_vstr(P->sem));
  int firstline = P->tokline;
  nextok(P);
  if (P->tok == '=') {
    /* numeric for */
    nextok(P);
    ls_Node *e1 = parse_expr(P);
    expect(P, ',', ",");
    ls_Node *e2 = parse_expr(P);
    ls_Node *e3 = NULL;
    if (accept(P, ',')) e3 = parse_expr(P);
    expect(P, TK_DO, "do");
    /* hidden slots: 3 control + var */
    int base = f->nextslot;
    addlocal(P, f, "(for state)", 0, line);
    addlocal(P, f, "(for state)", 0, line);
    addlocal(P, f, "(for state)", 0, line);
    int varslot = addlocal(P, f, first, 0, firstline);
    ls_BlkInfo *b = enterblock(P, f, 1);
    b->nactvar = f->nloc - 4; /* locals before for-state */
    while (!isblockfollow(P)) {
      if (P->tok == TK_RETURN) { nodelist_add(P, &b->node->list, &b->node->n, parse_stat(P)); break; }
      ls_Node *st = parse_stat(P);
      if (st) nodelist_add(P, &b->node->list, &b->node->n, st);
    }
    expect(P, TK_END, "end");
    /* compute closefrom including var slot if captured */
    int closefrom = -1;
    for (int i = f->nloc - 4; i < f->nloc; i++)
      if (f->locals[i].captured) {
        int s = f->locals[i].slot;
        if (closefrom < 0 || s < closefrom) closefrom = s;
      }
    leaveblock(P, f, b);
    /* leaveblock recomputes for body only; override with our range */
    if (closefrom >= 0) b->node->i1 = closefrom;
    /* pop the 4 hidden/var locals */
    f->nloc -= 4;
    ls_Node *nd = ls_newnode(P->S, S_FORNUM, line);
    nd->a = e1; nd->b = e2; nd->c = e3;
    nd->ilist = malloc(sizeof(int) * 2);
    nd->ilist[0] = varslot; nd->ilist[1] = base;
    nodelist_add(P, &nd->list, &nd->n, b->node);
    free(first);
    return nd;
  } else {
    /* generic for */
    char *names[64]; int lines[64];
    names[0] = first; lines[0] = firstline;
    int nv = 1;
    while (accept(P, ',')) {
      if (P->tok != TK_NAME) errnear(P, "<name> expected");
      names[nv] = strdup(ls_vstr(P->sem));
      lines[nv] = P->tokline;
      nv++;
      nextok(P);
    }
    expect(P, TK_IN, "in");
    int nex;
    ls_Node *h = parse_explist(P, &nex);
    expect(P, TK_DO, "do");
    int base = f->nextslot;
    addlocal(P, f, "(for state)", 0, line);
    addlocal(P, f, "(for state)", 0, line);
    addlocal(P, f, "(for state)", 0, line);
    addlocal(P, f, "(for state)", 0, line); /* closing value */
    int varslots[64];
    for (int i = 0; i < nv; i++) varslots[i] = addlocal(P, f, names[i], 0, lines[i]);
    ls_BlkInfo *b = enterblock(P, f, 1);
    b->nactvar = f->nloc - 4 - nv;
    while (!isblockfollow(P)) {
      if (P->tok == TK_RETURN) { nodelist_add(P, &b->node->list, &b->node->n, parse_stat(P)); break; }
      ls_Node *st = parse_stat(P);
      if (st) nodelist_add(P, &b->node->list, &b->node->n, st);
    }
    expect(P, TK_END, "end");
    int closefrom = -1;
    for (int i = f->nloc - 4 - nv; i < f->nloc; i++)
      if (f->locals[i].captured) {
        int s = f->locals[i].slot;
        if (closefrom < 0 || s < closefrom) closefrom = s;
      }
    leaveblock(P, f, b);
    if (closefrom >= 0) b->node->i1 = closefrom;
    f->nloc -= 4 + nv;
    ls_Node *nd = ls_newnode(P->S, S_FORIN, line);
    nd->ilist = malloc(sizeof(int) * nv);
    memcpy(nd->ilist, varslots, sizeof(int) * nv);
    nd->i1 = nv;
    nd->i2 = base;
    nd->list = h->list; nd->n = h->n;
    nodelist_add(P, &nd->list2, &nd->n2, b->node);
    for (int i = 0; i < nv; i++) free(names[i]);
    return nd;
  }
}

static ls_Node *parse_stat(ls_Parser *P) {
  int line = P->tokline;
  switch (P->tok) {
    case ';': nextok(P); return NULL;
    case TK_IF: return parse_if(P);
    case TK_WHILE: return parse_while(P);
    case TK_DO: {
      nextok(P);
      ls_Node *b = parse_block(P);
      expect(P, TK_END, "end");
      ls_Node *nd = ls_newnode(P->S, S_DO, line);
      nd->a = b;
      return nd;
    }
    case TK_FOR: return parse_for(P);
    case TK_REPEAT: return parse_repeat(P);
    case TK_FUNCTION: {
      nextok(P);
      int ismethod = 0; char *lname = NULL; int nline = 0;
      ls_Node *target = parse_funcname(P, &ismethod, &lname, &nline);
      ls_Node *body = parse_funcbody(P, line, ismethod);
      ls_Node *nd = ls_newnode(P->S, S_ASSIGN, line);
      nodelist_add(P, &nd->list, &nd->n, target);
      nodelist_add(P, &nd->list2, &nd->n2, body);
      free(lname);
      return nd;
    }
    case TK_LOCAL: return parse_local(P);
    case TK_RETURN: {
      nextok(P);
      ls_Node *nd = ls_newnode(P->S, S_RETURN, line);
      if (!isblockfollow(P) && P->tok != ';') {
        int n;
        ls_Node *h = parse_explist(P, &n);
        nd->list = h->list; nd->n = n;
      }
      accept(P, ';');
      return nd;
    }
    case TK_BREAK: {
      nextok(P);
      /* check in loop */
      int inloop = 0;
      for (ls_BlkInfo *b = P->fs->blks; b; b = b->parent)
        if (b->isloop) { inloop = 1; break; }
      if (!inloop) perr(P, "break outside a loop at line %d", line);
      return ls_newnode(P->S, S_BREAK, line);
    }
    case TK_GOTO: {
      nextok(P);
      if (P->tok != TK_NAME) errnear(P, "<name> expected");
      char *nm = strdup(ls_vstr(P->sem));
      ls_Node *nd = ls_newnode(P->S, S_GOTO, line);
      /* try to resolve immediately among visible labels */
      ls_FState *f = P->fs;
      int resolved = 0;
      for (ls_BlkInfo *b = f->blks; b && !resolved; b = b->parent) {
        for (ls_Label *l = b->labels; l; l = l->next) {
          if (strcmp(l->name, nm) == 0) {
            if (l->nactvar <= f->nloc) {
              nd->b = b->node; nd->i1 = l->block;
              resolved = 1;
            } else {
              ls_Label ll; ll.nactvar = l->nactvar; ll.line = l->line; ll.name = l->name;
              ls_Goto gg; gg.nactvar = f->nloc; gg.line = line; gg.name = nm;
              check_goto_locals(P, f, &gg, &ll);
              nd->b = b->node; nd->i1 = l->block;
              resolved = 1;
            }
            break;
          }
        }
        if (b->nactvar <= f->nloc || resolved) { /* continue search outward */ }
      }
      if (!resolved) {
        ls_Goto *g = calloc(1, sizeof(ls_Goto));
        g->name = nm; g->line = line; g->nactvar = f->nloc; g->node = nd;
        g->next = f->blks->gotos;
        f->blks->gotos = g;
      } else free(nm);
      nextok(P);
      return nd;
    }
    case TK_DBCOLON: {
      nextok(P);
      if (P->tok != TK_NAME) errnear(P, "<name> expected");
      char *nm = strdup(ls_vstr(P->sem));
      int l2 = P->tokline;
      nextok(P);
      expect(P, TK_DBCOLON, "::");
      ls_Node *nd = ls_newnode(P->S, S_LABEL, line);
      nd->val = ls_str(P->S, nm);
      /* stmt index: current block's count; but parse_stat adds node AFTER
         returning, so index = current n */
      addlabel(P, P->fs, P->fs->blks, nm, l2, P->fs->blks->node->n);
      free(nm);
      return nd;
    }
    default: {
      /* expression statement: call or assignment */
      ls_Node *e = parse_suffixed(P);
      if (P->tok == '=' || P->tok == ',') {
        ls_Node *nd = ls_newnode(P->S, S_ASSIGN, line);
        nodelist_add(P, &nd->list, &nd->n, e);
        while (accept(P, ',')) {
          nodelist_add(P, &nd->list, &nd->n, parse_suffixed(P));
        }
        expect(P, '=', "=");
        int n;
        ls_Node *h = parse_explist(P, &n);
        nd->list2 = h->list; nd->n2 = n;
        return nd;
      }
      if (e->kind != E_CALL && e->kind != E_METHOD)
        perr(P, "%s:%d: syntax error near '%s'", "", 0, "?"); /* placeholder fixed below */
      ls_Node *nd = ls_newnode(P->S, S_EXPR, line);
      nd->a = e;
      return nd;
    }
  }
}

/* ---------------- entry ---------------- */

ls_Value ls_load(ls_State *S, const char *src, size_t len, const char *chunkname,
                 ls_Value env, const char **err) {
  ls_Parser P;
  memset(&P, 0, sizeof(P));
  P.S = S;
  /* skip shebang */
  if (len >= 1 && src[0] == '#') {
    const char *nl = memchr(src, '\n', len);
    if (nl) { len -= (size_t)(nl - src) ; src = nl; }
    else len = 0;
  }
  P.p = src; P.end = src + len;
  P.line = 1;
  /* chunk display name */
  char disp[128];
  P.chunk = strdup(ls_chunkid(chunkname, disp, sizeof(disp)));
  jmp_buf jb;
  P.jb = &jb;
  ls_FState *mainf = NULL;
  ls_Value result = ls_nil();
  if (setjmp(jb) == 0) {
    nextok(&P);
    mainf = newfs(&P, NULL, 1);
    P.fs = mainf;
    mainf->p->line = 0;
    addlocal(&P, mainf, "_ENV", 0, 0);
    ls_Node *body = parse_block(&P);
    if (P.tok != TK_EOF) errnear(&P, "'<eof>' expected");
    mainf->p->body = body;
    mainf->p->nslots = mainf->nextslot;
    mainf->p->nups = mainf->nups;
    mainf->p->upinslot = mainf->upinslot;
    mainf->p->upupidx = mainf->upupidx;
    mainf->p->upnames = malloc(sizeof(char*) * (mainf->nups + 1));
    for (int i = 0; i < mainf->nups; i++) mainf->p->upnames[i] = strdup(ls_vstr(mainf->upnames[i]));
    mainf->p->isvararg = 1;
    mainf->p->nparams = 0;
    mainf->p->lastline = P.line;
    ls_Closure *cl = malloc(sizeof(ls_Closure));
    cl->p = mainf->p;
    cl->ups = malloc(sizeof(ls_Upval*) * (mainf->nups > 0 ? mainf->nups : 1));
    /* main chunk's upvalues: none expected (it has _ENV local);
       if any (shouldn't happen), bind to env */
    for (int i = 0; i < mainf->nups; i++) {
      ls_Upval *u = malloc(sizeof(ls_Upval));
      u->v = env.tag == LS_TNIL ? ls_nil() : env;
      u->ptr = &u->v;
      u->next = NULL;
      cl->ups[i] = u;
    }
    result.tag = LS_TFUNC;
    result.u.cl = cl;
    /* if env given (non-nil), we must override _ENV: store it in a special
       way: make _ENV slot... Actually simplest: if env provided, wrap:
       we set closure's proto body to assign? Instead: create an upvalue-based
       variant. Since main has _ENV as LOCAL slot 0, env must be passed as
       first arg... We handle env by making the loader (in eval) set slot 0. */
    if (env.tag != LS_TNIL) {
      /* mark proto: env override stored via a fake upvalue list */
      /* simplest: change body's _ENV local init — evaluator inits slot 0 to globals;
         we add a hidden upvalue carrying env */
      ls_Closure *cl2 = malloc(sizeof(ls_Closure));
      ls_Proto *np = malloc(sizeof(ls_Proto));
      *np = *mainf->p;
      /* add one upvalue: _ENV */
      int k = np->nups;
      np->upinslot = malloc(sizeof(int) * (k + 1));
      np->upupidx = malloc(sizeof(int) * (k + 1));
      np->upnames = malloc(sizeof(char*) * (k + 2));
      memcpy(np->upinslot, mainf->p->upinslot, sizeof(int) * k);
      memcpy(np->upupidx, mainf->p->upupidx, sizeof(int) * k);
      for (int i = 0; i < k; i++) np->upnames[i] = mainf->p->upnames[i];
      /* rewrite body: local _ENV slot0 gets init from upvalue k.
         Instead we wrap the body in a synthetic proto:
           function (_ENV_up...) — too complex. Take simpler route: */
      (void)cl2;
      result.u.cl = cl;
      /* store env in closure's extra slot: we abuse ups array capacity */
      cl->ups = realloc(cl->ups, sizeof(ls_Upval*) * (mainf->nups + 1));
      ls_Upval *eu = malloc(sizeof(ls_Upval));
      eu->v = env; eu->ptr = &eu->v; eu->next = NULL;
      cl->ups[mainf->nups] = eu;
      /* mark: proto nups+1 means env override present (hack) */
      np = NULL;
      cl->p = mainf->p;
      cl->p->nups = mainf->nups; /* unchanged */
      /* evaluator will check closure for extra env upvalue */
      cl->p = mainf->p;
      /* signal via a special marker: we set a field on proto? Add to closure:
         we don't have a field. Use ups count + flag: */
      /* We'll detect env-override by checking a sentinel in eval via proto flag */
      mainf->p->lastline = -mainf->p->lastline; /* marker: env override */
    }
  } else {
    *err = P.err;
    return ls_nil();
  }
  return result;
}

