/* close a block: pop locals, set closefrom */
static void leaveblock(ls_Parser *P, ls_FState *f, ls_BlkInfo *b) {
  /* compute closefrom: min slot of captured locals declared in this block */
  int closefrom = -1;
  for (int i = b->nactvar; i < f->nloc; i++)
    if (f->locals[i].captured) {
      int s = f->locals[i].slot;
      if (closefrom < 0 || s < closefrom) closefrom = s;
    }
  b->node->i1 = closefrom;
  /* pop locals declared in block */
  f->nloc = b->nactvar;
  f->blks = b->parent;
}

/* resolve/propagate pending gotos at end of block, then leaveblock */
static void endblock(ls_Parser *P, ls_FState *f, ls_BlkInfo *b) {
  ls_Goto *g = b->gotos;
  b->gotos = NULL;
  while (g) {
    ls_Goto *nx = g->next;
    if (!g->node->b) {
      /* try label-at-end-of-block rule */
      for (ls_Label *l = b->labels; l; l = l->next) {
        if (strcmp(l->name, g->name) == 0) {
          int last = 1;
          for (int i = l->block + 1; i < b->node->n; i++)
            if (b->node->list[i]->kind != S_LABEL) { last = 0; break; }
          if (last) {
            g->node->b = b->node;
            g->node->i1 = b->node->n;
          }
        }
      }
      if (!g->node->b) {
        if (b->parent) {
          g->next = b->parent->gotos;
          b->parent->gotos = g;
        } else {
          char full[600];
          snprintf(full, sizeof(full), "%s:%d: no visible label '%s' for <goto>",
                   P->chunk, g->line, g->name);
          P->err = strdup(full);
          longjmp(*P->jb, 1);
        }
      }
    }
    g = nx;
  }
  leaveblock(P, f, b);
}

