      g->next = b->parent->gotos;
      b->parent->gotos = g;
      /* keep it in b->gotos too would double-free; mark resolved-by-move */
      /* simpler: rebuild list below */
    }
  }
  /* rebuild goto list without propagated ones */
  if (b->parent) {
    ls_Goto *keep = NULL;
    ls_Goto *g = b->gotos;
    /* we appended moved ones to parent already; but they are still in b list.
       Instead of the above mess: reconstruct. */
    (void)keep; (void)g;
  }
  leaveblock(P, f, b);
  return b->node;
}

