  ls_Closure *cl2 = malloc(sizeof(ls_Closure));
  ls_Proto *np = malloc(sizeof(ls_Proto));
  *np = *mainf->p;
  /* add one upvalue: _ENV */
  int k = np->nups;
  np->upinslot = malloc(sizeof(int) * (k + 1));
  np->upupidx = malloc(sizeof(int) * (k + 1));
  np->upnames = malloc(sizeof(char*) * (k + 2));
  memcpy(np->upinslot, mainf->p->upinslot, sizeof(int) * k);
  memcpy(np->upupidx, mainf->p->upupidx, sizeof(int) * k);
  for (int i = 0; i < k; i++) np->upnames[i] = mainf->p->upnames[i];
